"""Rebuild the real-data EX-102 fixtures in this folder from the committed extracts.

The original EX-102 files live on www.sec.gov/Archives, which refuses the project's default
user agent (HTTP 403), so the files cannot be recorded yet. These fixtures carry the values
extracted earlier from the real files, written back as Schedule AL XML so they go through the
same raw, bronze and silver load as any tape. Each file's header comment says exactly what is
real and what is left out. Run from the repository root:

    uv run python tests/fixtures/tape/build_real_tapes.py
"""

import csv
import json
from pathlib import Path
from xml.sax.saxutils import escape

ROOT = Path(__file__).resolve().parents[3]
HERE = Path(__file__).resolve().parent
SAMPLES = ROOT / "data" / "samples"

NAMESPACE = "http://www.sec.gov/edgar/document/absee/cmbs/assetdata"
DEFEASED = "Defeased"

# TSV column -> Schedule AL tag, loan level then property level.
LOAN_TAGS = {
    "endBal": "reportPeriodEndActualBalanceAmount",
    "paidThrough": "paidThroughDate",
    "status": "paymentStatusLoanCode",
    "ssTransfer": "mostRecentSpecialServicerTransferDate",
    "msReturn": "mostRecentMasterServicerReturnDate",
    "workout": "workoutStrategyCode",
    "modCode": "modificationCode",
    "liqCode": "liquidationPrepaymentCode",
}
PROPERTY_TAGS = {
    "name": "propertyName",
    "type": "propertyTypeCode",
    "finSecDate": "financialsSecuritizationDate",
    "finStart": "mostRecentFinancialsStartDate",
    "finEnd": "mostRecentFinancialsEndDate",
    "noi": "mostRecentNetOperatingIncomeAmount",
    "dscrNOI": "mostRecentDebtServiceCoverageNetOperatingIncomePercentage",
    "occ": "mostRecentPhysicalOccupancyPercentage",
}


def _elements(values: dict[str, str], tags: dict[str, str], indent: str) -> list[str]:
    """Only reported values become elements: a missing tag means "not reported"."""
    return [
        f"{indent}<{tag}>{escape(values[column])}</{tag}>"
        for column, tag in tags.items()
        if values.get(column)
    ]


def asset_xml(values: dict[str, str], period_end: str) -> str:
    lines = [
        "  <assets>",
        "    <assetTypeNumber>Prospectus Loan ID</assetTypeNumber>",
        f"    <assetNumber>{escape(values['id'])}</assetNumber>",
        f"    <reportingPeriodEndDate>{period_end}</reportingPeriodEndDate>",
        *_elements(values, LOAN_TAGS, "    "),
    ]
    prop = _elements(values, PROPERTY_TAGS, "      ")
    if prop:
        lines += ["    <property>", *prop, "    </property>"]
    lines.append("  </assets>")
    return "\n".join(lines)


def tape_xml(comment: str, assets: list[dict[str, str]], period_end: str) -> str:
    body = "\n".join(asset_xml(values, period_end) for values in assets)
    return (
        '<?xml version="1.0" encoding="UTF-8"?>\n'
        f"<!--\n{comment.strip()}\n-->\n"
        f'<assetData xmlns="{NAMESPACE}">\n{body}\n</assetData>\n'
    )


def bnk13_september() -> str:
    source = SAMPLES / "bank-2018-bnk13" / "absee_2026-09_loans.tsv"
    lines = source.read_text().splitlines()
    rows = list(csv.DictReader(lines[1:], delimiter="\t"))
    for row in rows:
        # Property names name real companies; only the defeasance marker is kept.
        if row["name"] != DEFEASED:
            row["name"] = ""
    comment = f"""
BANK 2018-BNK13 (CIK 1744707), September 2026 ABS-EE, accession 0001888524-26-017705,
filed 2026-09-29, reportingPeriodEndDate 09-11-2026.
Rebuilt from data/samples/bank-2018-bnk13/absee_2026-09_loans.tsv, which was extracted from
the real exh_102.xml. {len(rows)} top-level loans; companion notes and portfolio properties are
not in the extract. Every value is as extracted, except: property names are left out (they
name real companies), apart from the "Defeased" marker; tags the extract did not keep are
absent. Generated by tests/fixtures/tape/build_real_tapes.py.
"""
    return tape_xml(comment, rows, "09-11-2026")


def bnk13_august() -> str:
    source = SAMPLES / "bank-2018-bnk13" / "timeseries_2025-08_to_2026-09.json"
    series = json.loads(source.read_text())["ditson_building_loan11"]
    header, rows = series[0], series[1:]
    july = dict(zip(header, rows[-2], strict=True))  # 07-13-2026, the last row before August
    assert july["rpEnd"] == "07-13-2026"
    loan = {
        "id": "11",
        "paidThrough": july["paidThrough"],
        "status": july["status"],
        "ssTransfer": july["ssTransfer"],
        "workout": july["workout"],
        "type": "OF",
        "finStart": july["finStart"],
        "finEnd": july["finEnd"],
        "noi": f"{july['noi']:.2f}",
        "dscrNOI": str(july["dscr"]),
        "occ": str(july["occ"]),
    }
    comment = """
BANK 2018-BNK13 (CIK 1744707), August 2026 ABS-EE, accession 0001888524-26-015516,
filed 2026-08-27, reportingPeriodEndDate 08-11-2026.
Rebuilt for loan 11 only, from data/samples/bank-2018-bnk13/timeseries_2025-08_to_2026-09.json:
its values in July 2026, which the recorded status events show unchanged in August (the next
change, workout 13 to 2, is in September). Property type OF is from the September extract.
The ending balance and the other loans are not in the extracts and are left out.
Generated by tests/fixtures/tape/build_real_tapes.py.
"""
    return tape_xml(comment, [loan], "08-11-2026")


def bank5_5yr23_september() -> str:
    source = SAMPLES / "_cross_section" / "staleness_2026-09.json"
    deal = next(d for d in json.loads(source.read_text())["deals"] if d["cik"] == 2140978)
    assert deal["active"] == 33 and deal["withFin"] == 0
    loans = [
        {"id": str(number), "endBal": "1000000.00", "status": "0"}
        for number in range(1, deal["active"] + 1)
    ]
    comment = f"""
BANK5 2026-5YR23 (CIK 2140978), September 2026 ABS-EE, accession {deal["acc"]},
filed 2026-10-01, reportingPeriodEndDate 09-11-2026. The deal closed in June 2026.
Verified facts (research/11-data-sources.md section 1.7, data/samples/_cross_section): 33
active top-level loans and no mostRecent* financials tags on any of them. The loan numbers,
the 1,000,000.00 ending balances and payment status 0 are placeholders standing in for values
not in the extracts; no scenario reads them.
Generated by tests/fixtures/tape/build_real_tapes.py.
"""
    return tape_xml(comment, loans, "09-11-2026")


FIXTURES = {
    "bank-2018-bnk13_2026-09_ex102.xml": bnk13_september,
    "bank-2018-bnk13_2026-08_ex102.xml": bnk13_august,
    "bank5-2026-5yr23_2026-09_ex102.xml": bank5_5yr23_september,
}


if __name__ == "__main__":
    for name, build in FIXTURES.items():
        (HERE / name).write_text(build())
        print(f"wrote {name}")
